async function putPackage(r,assets){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction(['assets','packages'],'readwrite'),s=tx.objectStore('assets');for(const t of assets.tiles)s.put(t.blob,r.id+'/'+t.key);if(assets.image)s.put(assets.image,r.id+'/image');if(assets.source)s.put(assets.source,r.id+'/source');tx.objectStore('packages').put(r,r.id);tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||Error('Cihazda yer kalmadı; önceki harita korundu.'));tx.onerror=()=>reject(tx.error);});}
