function toggle(k){const s=getState();defaults(s);s.raceLayers[k]=!s.raceLayers[k];save();render();api.targetsVisible(s.raceLayers);api.refreshPanel();if(['pz','boundary','grid'].includes(k)&&!s.raceLayers[k]&&s.raceLayers.map&&s.race?.mapType)toast('Vektör katmanı gizlendi. Resme basılı işaretler için Diğer → Harita’yı da kapatabilirsiniz.');}
function note(z){return z.color==='yellow'?'Sarı PZ · kalkış / iniş kısıtı':z.color==='blue'?'Mavi PZ · irtifa sınırı':'Kırmızı PZ · kısıtlı bölge';}
